export const graphsMeta={slug:'algorithms/graphs',title:'Graph Algorithms',description:'Choose the representation and objective: reachability, distances, dependencies, connectivity, spanning trees or every-edge routes.',date:'2026-07-24',updated:'2026-10-14',topicPath:['algorithms'],tags:['graphs','DFS','BFS','Dijkstra','Bellman-Ford','Floyd-Warshall','Union-Find','MST','Euler','topological'],prototype:true,visibility:'public',kind:'dense-topic',learningGoals:['Choose the edge/objective contract before the frontier.','Implement visited and stale-entry state correctly.','Separate connectivity,source distance and spanning-tree objectives.'],related:['algorithms/trees','algorithms/dp','algorithms/ordering']};
export const graphsAliases=[];
export const graphsSections=[['objective','Start with the relationship and objective'],['representation','Store neighbors, not accidental assumptions'],['reachability','DFS remembers what has been entered'],['bfs','BFS discovers shortest edge counts'],['bfs-code','Return the first target distance'],['bfs-lab','A queue expands by edge distance'],['cycles','Cycles and prerequisites need different state'],['connectivity','Union-Find maintains components'],['dsu-code','Join components with rank and path halving'],['relaxation','A tentative path can improve'],['dijkstra','Finalize the current minimum, not the first discovery'],['dijkstra-code','Compute reached weighted distances with a lazy heap'],['dijkstra-lab','A cheaper indirect path changes the frontier'],['zero-one','Two distance levels replace the heap'],['negative','Negative weights and bounded-edge states'],['all-pairs','Floyd–Warshall adds allowed intermediates'],['mst','A spanning tree has another objective'],['euler','Use every edge: defer route output until stuck'],['practice','Check the graph contract and total work'],['sources','Sources and related patterns']];
const graph=[[[1,8],[2,1]],[[3,1]],[[1,1],[3,10]],[]],nodes=[{name:'A',x:60,y:150},{name:'B',x:250,y:60},{name:'C',x:250,y:240},{name:'D',x:440,y:150}],edges=graph.flatMap((es,i)=>es.map(([j,w])=>[i,j,w])),bf=bfsTrace(graph,0),df=dijkstraTrace(graph,0),num=d=>d===null?'unknown':d===Infinity?'∞':d;
const bfsBody=f=>`${graphSvg(nodes,edges,{active:f.current,done:f.processed,directed:true,weights:true})}<p>${f.message}</p><p>Queue front → back: ${f.queue.map(i=>nodes[i].name).join(' → ')||'empty'}. Processed: ${f.processed.map(i=>nodes[i].name).join(', ')||'none'}.</p>${table('Edge-count distances',['A','B','C','D'],[f.distance.map(num)])}<p>Ignore the drawn weights for this objective. The first route to D follows A→B→D: two edges, weight 9, not the minimum weighted cost.</p>`;
const dijkstraBody=f=>`${graphSvg(nodes,edges,{active:f.current,done:f.settled,highlight:f.edge,directed:true,weights:true})}<p>${f.message}</p>${table('Tentative weighted distances',['A','B','C','D'],[f.distance.map(num)])}<p>Settled: ${f.settled.map(i=>nodes[i].name).join(', ')||'none'}. Pending entries (distance:vertex): ${[...f.queue].sort((a,b)=>a[0]-b[0]||a[1]-b[1]).map(([d,i])=>`${d}:${nodes[i].name}`).join(' · ')||'empty'}.</p><p>Blue-filled nodes are settled. A blue edge is the edge currently relaxed. Distances elsewhere can still change.</p>`;
export function graphsReader(link){return topic(graphsMeta,graphsSections,'The edge contract determines which frontier can be trusted.',`
<p>A graph connects entities by arbitrary relationships. The same vertices can support several different questions: which nodes are reachable, how cheap is a route, which prerequisite can run next, or how cheaply can all nodes be connected?</p><p>Choose that objective first. Then choose a representation and an invariant. A queue, stack, heap or disjoint-set structure is useful only because its state matches the question.</p>
${section('objective','Start with the relationship and objective',table('Choose by edge and objective conditions',['Question/condition','Candidate','Important limit'],[['Reachability or components','DFS/BFS','One source does not cover disconnected components'],['Fewest edges / equal positive costs','BFS','Arbitrary weights invalidate first-discovery optimality'],['Nearest among several sources','Multi-source BFS','Seed all sources at distance zero'],['Nonnegative weighted shortest path','Dijkstra','First enqueue is tentative, not final'],['Weighted DAG, even negative edges','Topological relaxation','Requires an acyclic directed graph'],['Negative edges, possible cycles','Bellman–Ford','A reachable negative cycle can destroy finite optimum'],['All-pairs paths, small graph','Floyd–Warshall','Cubic time and quadratic distance storage'],['Minimum total connecting tree','Prim/Kruskal','Not a source-distance objective'],['Every edge once','Hierholzer','Degree/connectivity conditions must permit such a route']]))}
${section('representation','Store neighbors, not accidental assumptions',`<p>An adjacency list includes a list for every vertex, including isolated nodes and destinations with no outgoing edges. Directed u→v adds only that direction. Undirected edges usually add both directions; parallel edges and self-loops need an explicit policy.</p><pre tabindex="0" role="region" aria-label="Adjacency list Python"><code>def adjacency_list(vertex_count, edges, directed=True):
    graph = [[] for _ in range(vertex_count)]
    for source, destination in edges:
        graph[source].append(destination)
        if not directed: graph[destination].append(source)
    return graph</code></pre><p>The adjacency representation stores O(V+E) entries, counting an undirected edge's two incidences only as a constant factor. A dense matrix uses O(V²) space. Neighbor traversal through a matrix can change the cost of an otherwise linear algorithm.</p><p>The constructor expects vertex indices from zero through vertex_count−1 and a nonnegative vertex count. It keeps isolated vertices and does not deduplicate parallel incidences. An undirected self-loop appears twice under this incidence convention.</p><p>A grid is an implicit graph: cells are vertices and permitted moves are edges. Check bounds, obstacles and whether four or eight neighbors are permitted. Four-neighbor moves change one row or column index by one, never both. Height-based reachability may reverse the direction of the search; a reversed edge rule is not automatically an undirected relation.</p>`)}
${section('reachability','DFS remembers what has been entered',`<p>Mark a vertex on entry before recursively exploring unvisited neighbors. Otherwise a cycle can revisit the active path forever. Repeat from every unvisited vertex to find all undirected components.</p><pre tabindex="0" role="region" aria-label="Graph reachability Python"><code>def reachable(graph, start):
    visited = set()
    def visit(node):
        if node in visited: return
        visited.add(node)
        for neighbor in graph[node]: visit(neighbor)
    visit(start)
    return visited</code></pre><p>The function returns the reached vertices and creates a fresh set for each query. Every reached vertex must have an adjacency entry, even if that entry is empty.</p><p>This visited set means “already entered anywhere.” It is different from an on-path set used to enumerate simple paths. Removing a globally visited mark on return changes the algorithm into repeated path exploration. <a href="${link('algorithms/trees')}">Tree returns and traversals →</a> use simpler structure when there are no cycles or shared subtrees.</p><p>Cloning a graph needs an original-node→clone map before traversing its neighbors. A boolean visited flag alone does not provide the cloned endpoint. Recursive DFS uses stack depth up to O(V); an explicit stack avoids call-depth limits but still needs pending state.</p>`)}
${section('bfs','BFS discovers shortest edge counts',`<p>A FIFO queue processes increasing edge-distance layers. Mark a vertex when enqueuing, not later when popping, so multiple incoming edges do not enqueue duplicate copies. Its first discovery is a shortest edge-count path.</p><details id="bfs-code"><summary>Return the first target distance</summary><pre tabindex="0" role="region" aria-label="Unweighted shortest distance Python"><code>def shortest_distance(graph, start, is_target):
    from collections import deque
    queue = deque([(start, 0)])
    visited = {start}
    while queue:
        node, distance = queue.popleft()
        if is_target(node): return distance
        for neighbor in graph[node]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, distance + 1))
    return -1</code></pre></details><p>Pass a target predicate such as lambda node: node == target. A target source returns zero; no reached target returns −1. To reconstruct one shortest path, also record parent[neighbor]=node at enqueue time. One parent per vertex does not encode every shortest path.</p><p>For multi-source BFS, enqueue all distinct sources at distance zero. A first discovery then gives distance to the nearest source. This handles spread from several origins or distance to the nearest marked cell; source ownership ties need a deterministic policy if reported.</p>${traceLab('bfs-lab','A queue expands by edge distance','Directed example A→B(8), A→C(1), C→B(1), B→D(1), C→D(10). BFS deliberately ignores weights and minimizes edge count.',bf,bf.length-1,bfsBody)}`)}
${section('cycles','Cycles and prerequisites need different state',`<p>For a simple undirected graph, a visited neighbor other than the traversal parent signals a cycle. In a multigraph, identify the parent edge rather than skipping every edge to the parent vertex: a parallel edge can itself close a cycle.</p><p>For directed DFS, distinguish unvisited, active on the recursive path and finished. An edge to an active vertex closes a directed cycle. An edge to a finished vertex can merely join an already explored branch.</p><p>Kahn's topological algorithm counts incoming edges, queues every zero-indegree vertex, removes one and decrements its outgoing neighbors. Processing fewer than V vertices means a directed cycle remains. A topological order respects every prerequisite edge; it need not be unique.</p><p>When deriving ordering constraints from adjacent dictionary words, the first differing character contributes an edge. A longer word before its own prefix is inconsistent even when no character-cycle is found. Include characters that have no inferred edges.</p>`)}
${section('connectivity','Union-Find maintains components',`<p>Disjoint Set Union (DSU) stores a representative for each connected component under edge additions. find returns a root; union joins two different roots or reports that the endpoints were already connected. It does not store a traversal path.</p><details id="dsu-code"><summary>Join components with rank and path halving</summary><pre tabindex="0" role="region" aria-label="Union Find Python"><code>class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n
    def find(self, node):
        while node != self.parent[node]:
            self.parent[node] = self.parent[self.parent[node]]
            node = self.parent[node]
        return node
    def union(self, a, b):
        root_a, root_b = self.find(a), self.find(b)
        if root_a == root_b: return False
        if self.rank[root_a] &lt; self.rank[root_b]:
            root_a, root_b = root_b, root_a
        self.parent[root_b] = root_a
        if self.rank[root_a] == self.rank[root_b]:
            self.rank[root_a] += 1
        return True</code></pre></details><p>The class expects n nonnegative and every queried vertex in range(n). Its parent links start as a valid forest. Union by rank attaches the lower-rank root; only equal ranks cause an increment. Rank is a bound used for linking, not the current exact height after compression. With both mechanisms, total operation cost is amortized O(α(V)) in the usual model.</p><p>DSU detects redundant undirected edges and supports Kruskal's algorithm. A standard DSU does not directly handle arbitrary edge deletions or directed reachability. A successful union returns True; repeated connections and self-unions return False.</p>`)}
${section('relaxation','A tentative path can improve',`${eq("\\begin{aligned}c&=d_u+w(u,v)\\\\c<d_v&\\ \\Longrightarrow\\ (d_v,\\pi_v)\\leftarrow(c,u)\\end{aligned}","For a reached vertex u, du is its tentative distance, w(u,v) is edge weight and πv is the predecessor. Strict improvement replaces both distance and predecessor. Guard unreachable sentinels and overflow. Relaxation is not finalization; Dijkstra additionally requires nonnegative weights.")}<p>Initialize the source to zero and others to infinity. A strict improvement updates the predecessor. Equal-cost routes can leave the existing predecessor unchanged; a different tie policy must preserve correctness and avoid cycles in reconstruction.</p><p>In the example, B is first discovered at cost 8. A→C→B lowers that to 2, and B→D then lowers D to 3. Any policy that freezes B on first discovery misses this route.</p>`)}
${section('dijkstra','Finalize the current minimum, not the first discovery',`<p>Pop the smallest tentative distance. If the entry no longer matches the stored distance, discard it as stale. Otherwise nonnegative weights make this current minimum final: another unsettled route cannot cross the frontier and reduce it below that minimum.</p><details id="dijkstra-code"><summary>Compute reached weighted distances with a lazy heap</summary><pre tabindex="0" role="region" aria-label="Dijkstra Python"><code>def dijkstra(graph, source):
    from heapq import heappop, heappush
    from itertools import count
    serial = count()
    distances = {source: 0}
    heap = [(0, next(serial), source)]
    while heap:
        distance, _, node = heappop(heap)
        if distance != distances[node]: continue
        for neighbor, weight in graph[node]:
            if weight &lt; 0: raise ValueError('negative reachable edge')
            candidate = distance + weight
            if candidate &lt; distances.get(neighbor, float('inf')):
                distances[neighbor] = candidate
                heappush(heap, (candidate, next(serial), neighbor))
    return distances</code></pre></details><p>The function expects finite nonnegative weights and an adjacency entry for each vertex. It returns only reached distances. It rejects a negative edge if encountered; callers still own the complete input contract. A monotonically increasing serial breaks equal-distance heap ties without comparing vertex objects. Do not mark a node final when pushing. Early exit for a target is safe at its current-minimum pop, not at its first discovery.</p><p>A lazy heap can retain O(E) entries, with O((V+E) log(V+E)) as a safe general bound. An indexed decrease-key heap has different storage and accounting. The lab sorts a tiny candidate list to display exact priority order; it is not a performance implementation.</p>${traceLab('dijkstra-lab','A cheaper indirect path changes the frontier','Same vertices and weights as the BFS lab. Dijkstra settles A,C,B,D at costs 0,1,2,3, then discards old entries for B and D.',df,df.length-1,dijkstraBody)}`)}
${section('zero-one','Two distance levels replace the heap',`<p>When every edge costs zero or one, the ordered frontier needs only two adjacent distance levels. A zero-cost improvement stays at the current level; a one-cost improvement waits behind it. Use a deque: add the first to its front and the second to its back. Strict relaxation, not first-discovery marking, permits a cheaper route to replace an earlier one.</p><p>Consider directed edges A→B with cost1, A→C with cost0, and C→B with cost0. Ordinary edge-count BFS prefers the direct route. The minimum weighted cost is instead zero:</p>${table('Front of the deque is on the left',['Operation','Pending entries','Best reached distances'],[['Start','A:0','A=0'],['Expand A; inspect B then C','C:0, B:1','A=0, B=1, C=0'],['Expand C; improve B','B:0, B:1','A=0, B=0, C=0'],['Expand B:0; discard stale B:1','Empty','A=0, B=0, C=0']])}<pre tabindex="0" role="region" aria-label="Zero-one BFS Python"><code>def zero_one_bfs(graph, source):
    from collections import deque
    distances, frontier = {source: 0}, deque([(source, 0)])
    while frontier:
        node, distance = frontier.popleft()
        if distance != distances[node]: continue
        for neighbor, weight in graph[node]:
            if weight not in (0, 1): raise ValueError('0/1 weights required')
            candidate = distance + weight
            if candidate &gt;= distances.get(neighbor, float('inf')): continue
            distances[neighbor] = candidate
            entry = (neighbor, candidate)
            if weight == 0: frontier.appendleft(entry)
            else: frontier.append(entry)
    return distances</code></pre><p>This function returns reached distances and does not mutate adjacency. Every vertex needs an adjacency entry; labels must be hashable. Invalid encountered weights raise an error. Strict improvement terminates zero-cost cycles. Stored distances identify stale entries without comparing vertex labels. With bounded-cost operations, traversal takes O(V+E) work; lazy frontier storage can take O(E), besides O(V) distances. General nonnegative weights still need another frontier. ${cite('https://cp-algorithms.com/graph/01_bfs.html','0–1 frontier argument')}</p>`)}
${section('negative','Negative weights and bounded-edge states',`<p>Bellman–Ford repeatedly relaxes every edge. Without a reachable negative cycle, a shortest simple path needs at most V−1 edges, so V−1 passes suffice. A further successful relaxation detects a source-reachable negative cycle; unreachable cycles do not affect that source's finite paths.</p><p>Which targets have no finite minimum depends on whether they are reachable from such a cycle. State this rather than returning a normal distance for every vertex. Runtime is O(VE); an unchanged pass can stop early.</p><p>A weighted directed acyclic graph permits one topological relaxation pass even with negative weights, because dependencies never lead back. For a maximum edge budget, use a separate distance layer for each allowed edge count. Read only the previous layer to enforce that budget. K stops normally permits K+1 edges; check the definition.</p>${eq("d^{(k)}_v=\\min\\!\\left(d^{(k-1)}_v,\\min_{(u,v)\\in E}\\bigl[d^{(k-1)}_u+w(u,v)\\bigr]\\right)","Here d⁽ᵏ⁾v is the least cost of a source-to-v walk using at most k edges. Initialize d⁽⁰⁾source=0 and other vertices to infinity. The minimum over no incoming edges is infinity. Copy the previous layer before relaxing all edges; in-place reuse would permit extra edges in one pass. A finite budget bounds walk length even when negative cycles exist.")}`)}
${section('all-pairs','Floyd–Warshall adds allowed intermediates',`${eq("D^{(k)}_{ij}=\\min\\!\\left(D^{(k-1)}_{ij},D^{(k-1)}_{ik}+D^{(k-1)}_{kj}\\right)","Number vertices1…V; D⁽ᵏ⁾ permits intermediate vertices1…k. D⁽⁰⁾ uses direct edges and zero-length diagonal paths. Use extended-distance sentinels safely. The intermediate k is the outer loop; reachable negative cycles need a separate unbounded-below result.")}<p>Initialize diagonal distances to zero and each direct edge to its smallest weight if parallel edges exist. Use infinity for missing edges and avoid invalid arithmetic with sentinels. The usual in-place recurrence uses intermediate k as the outer loop; arbitrary loop reordering changes its meaning.</p><p>Time is O(V³), storage O(V²). A negative diagonal reveals a negative cycle. Paths that can pass through such a cycle need a separate “unbounded below” result, not a finite shortest-distance claim.</p>`)}
${section('mst','A spanning tree has another objective',`<p>An undirected minimum spanning tree connects every vertex without cycles while minimizing total selected edge weight. It does not minimize each source-to-vertex route. In a disconnected graph, the analogous result is a minimum spanning forest.</p><p>Kruskal sorts edges by weight and uses DSU to accept an edge only when it joins different components. Prim grows one tree by its cheapest outgoing crossing edge. Their cut argument makes a light crossing edge safe for some MST; ties can produce several optimal trees.</p><p>Negative weights are allowed for MSTs, unlike Dijkstra's standard invariant. Counting a source path and summing all connecting edges are different objectives even when both implementations use heaps. Kruskal costs sorting plus near-linear DSU work; Prim's bound depends on its queue implementation.</p>`)}
${section('euler','Use every edge: defer route output until stuck',`<p>An Euler route uses every edge exactly once; revisiting vertices is permitted. A Hamiltonian route instead visits vertices, which is a different and generally harder task.</p><p>Hierholzer follows unused edges on a stack. When the top has none left, pop that vertex into the output. Reverse the resulting postorder list. Use edge identities so parallel edges remain distinct. Mutating adjacency consumes input unless it was copied.</p><p>For directed routes, an open trail has one vertex with outdegree−indegree=1, one with −1 and all others balanced; a circuit has every vertex balanced. The nonzero-degree vertices must be connected in the appropriate underlying support. Undirected routes need zero or two odd-degree vertices and connected non-isolated support. Verify that output uses E edges; do not silently return a partial traversal.</p><p>Lexical ordering adds an ordered unused-edge policy and valid start selection. Sorting adjacency in reverse for pop-from-end can provide that policy, but degree and connectivity feasibility still come first.</p>`)}
${section('practice','Check the graph contract and total work',`<p>Record direction, parallel edges, self-loops, weights, isolated vertices, source set and objective. DFS/BFS on adjacency lists take O(V+E) traversal work and O(V) auxiliary state; the representation itself also occupies O(V+E). A four-neighbor grid has O(rows·columns) vertices and edges.</p><p>Test unreachable targets, several components, repeated edges, a diamond with two discoveries, zero weights, a tempting expensive direct route and a negative cycle when supported. Restore shared grids after path-specific search when the API requires it.</p><p><a href="${link('algorithms/dp')}">Dynamic Programming →</a> explains layer states and dependency order. It is directly connected to bounded-edge paths, DAG relaxation and all-pairs intermediates.</p>`)}
${section('sources','Sources and related patterns',`<p>${cite('https://algs4.cs.princeton.edu/41graph/','Traversal and representations')} · ${cite('https://algs4.cs.princeton.edu/44sp/','Weighted path conditions')} · ${cite('https://algs4.cs.princeton.edu/43mst/','Spanning-tree objective and cut property')}</p><p><a href="${link('algorithms/ordering#heap')}">Heap invariants →</a> and <a href="${link('algorithms/ordering#priority')}">priority keys and ties →</a> explain the ordered frontier used here.</p>`)}
`);}
graphsMeta.searchText=graphsReader(()=> '').replace(/<[^>]*>/g,' ');
export function mountGraphs(scope=document){mountTopic(scope,graphsMeta.slug,article=>{mountTrace(article,'bfs-lab',bf,bfsBody);mountTrace(article,'dijkstra-lab',df,dijkstraBody);});}
